INSERT INTO litemall_comment (id, value_id, order_id, order_goods_id, type, content, admin_content, reply_time, user_id, has_picture, pic_urls, star, status, add_time, update_time, deleted) VALUES
  (999001, 993005, 998020, 998224, 0, '收纳箱很结实，折叠后不占地方，回购了第二个。', '', NULL, 991103, 0, NULL, 5, 0, DATE_SUB(NOW(), INTERVAL 4200 MINUTE), DATE_SUB(NOW(), INTERVAL 4200 MINUTE), 0),
  (999002, 993006, 998021, 998225, 0, '白茶味很清新，燃烧时间也够长。', '', NULL, 991101, 0, NULL, 4, 0, DATE_SUB(NOW(), INTERVAL 7080 MINUTE), DATE_SUB(NOW(), INTERVAL 7080 MINUTE), 0),
  (999003, 993001, 998021, 998226, 0, '面料很舒服，白色不透，尺码正常。', '', NULL, 991101, 0, NULL, 5, 0, DATE_SUB(NOW(), INTERVAL 7080 MINUTE), DATE_SUB(NOW(), INTERVAL 7080 MINUTE), 0),
  (999004, 993004, 998022, 998227, 0, '低音下潜不错，降噪通勤够用。', '感谢支持，已为您登记一年延保～', DATE_SUB(NOW(), INTERVAL 11340 MINUTE), 991102, 0, NULL, 5, 0, DATE_SUB(NOW(), INTERVAL 11400 MINUTE), DATE_SUB(NOW(), INTERVAL 11400 MINUTE), 0),
  (999005, 993012, 998023, 998228, 0, '颜色偏深，和图片有色差。', '', NULL, 991103, 0, NULL, 2, 1, DATE_SUB(NOW(), INTERVAL 17160 MINUTE), DATE_SUB(NOW(), INTERVAL 17160 MINUTE), 0),
  (999006, 993009, 998024, 998229, 0, '亮度均匀，夜里写字不刺眼。', '', NULL, 991101, 0, NULL, 4, 0, DATE_SUB(NOW(), INTERVAL 22920 MINUTE), DATE_SUB(NOW(), INTERVAL 22920 MINUTE), 0),
