-- ============================================================================
-- R2 演示种子数据（Q21 口径）
-- 生成脚本：.tmp/t8/gen_seed.py（只读参考，不随仓库发布）
-- 口径：需求文档 8-Q21 + docs/impl/05-R2实施口径.md §8.1 + CI-08 报表 SQL（§2.1.3）
-- 特性：可重复执行（按固定 ID 段先删后插）；时间全部相对 NOW()，重跑后仍在近 30 天；
--       金额以分为单位精确计算，订单实付 = 商品金额 + 运费 - 券抵扣；券额按 D9 分摊、尾差入末行。
-- 不执行任何 DDL；仅 DML（DELETE 本脚本 ID 段 + INSERT）。
-- ID 段：admin 9912xx / user 9911xx / address 9913xx / category 9921xx / brand 9922xx /
--         goods 9930xx / product 9931xx / specification 9932xx / coupon 9940xx / coupon_user 9941xx /
--         ad 9950xx / topic 9960xx / notice 9970xx / order 9980xx / order_goods 9982xx /
--         aftersale 9985xx / refund 9986xx / comment 9990xx / log 9991xx
-- ============================================================================
SET NAMES utf8mb4;

START TRANSACTION;

-- ---------------------------------------------------------------- 清理旧种子（只删本脚本占用的精确 ID）
-- 用 IN (精确 ID) 而非 BETWEEN 宽段：本机库已有其他 cohort 在相邻号段写入数据
-- （如 admin 991203+、log 999109+），宽段 DELETE 会误删正在验收使用的行。
DELETE FROM litemall_refund WHERE id IN (998601, 998602, 998603);
DELETE FROM litemall_aftersale WHERE id IN (998501, 998502, 998503, 998504, 998505, 998506, 998507, 998508);
DELETE FROM litemall_comment WHERE id IN (999001, 999002, 999003, 999004, 999005, 999006, 999007, 999008, 999009, 999010, 999011, 999012, 999013, 999014, 999015, 999016, 999017);
DELETE FROM litemall_order_goods WHERE id IN (998201, 998202, 998203, 998204, 998205, 998206, 998207, 998208, 998209, 998210, 998211, 998212, 998213, 998214, 998215, 998216, 998217, 998218, 998219, 998220, 998221, 998222, 998223, 998224, 998225, 998226, 998227, 998228, 998229, 998230, 998231, 998232, 998233, 998234, 998235, 998236, 998237, 998238, 998239, 998240, 998241, 998242, 998243, 998244, 998245);
DELETE FROM litemall_order WHERE id IN (998001, 998002, 998003, 998004, 998005, 998006, 998007, 998008, 998009, 998010, 998011, 998012, 998013, 998014, 998015, 998016, 998017, 998018, 998019, 998020, 998021, 998022, 998023, 998024, 998025, 998026, 998027, 998028, 998029, 998030, 998031, 998032, 998033, 998034, 998035);
DELETE FROM litemall_coupon_user WHERE id IN (994101, 994102, 994103, 994104, 994105);
DELETE FROM litemall_coupon WHERE id IN (994001, 994002, 994003, 994004);
DELETE FROM litemall_goods_product WHERE id IN (993101, 993102, 993103, 993104, 993105, 993106, 993107, 993108, 993109, 993110, 993111, 993112, 993113, 993114, 993115, 993116);
DELETE FROM litemall_goods_specification WHERE id IN (993201, 993202, 993203, 993204, 993205, 993206, 993207, 993208, 993209, 993210, 993211, 993212, 993213, 993214, 993215, 993216);
DELETE FROM litemall_goods WHERE id IN (993001, 993002, 993003, 993004, 993005, 993006, 993007, 993008, 993009, 993010, 993011, 993012);
DELETE FROM litemall_category WHERE id IN (992101, 992102, 992103, 992111, 992112, 992113);
DELETE FROM litemall_brand WHERE id IN (992201, 992202, 992203, 992204);
DELETE FROM litemall_ad WHERE id IN (995001, 995002, 995003);
DELETE FROM litemall_topic WHERE id IN (996001, 996002);
DELETE FROM litemall_notice WHERE id IN (997001, 997002, 997003);
DELETE FROM litemall_log WHERE id IN (999101, 999102, 999103, 999104, 999105, 999106, 999107, 999108);
DELETE FROM litemall_address WHERE id IN (991301, 991302, 991303);
DELETE FROM litemall_user WHERE id IN (991101, 991102, 991103);
DELETE FROM litemall_admin WHERE id IN (991201, 991202);

-- ---------------------------------------------------------------- 账号 / 用户 / 地址



-- ---------------------------------------------------------------- 分类 / 品牌


-- ---------------------------------------------------------------- 商品 / 规格 / SKU



-- ---------------------------------------------------------------- 优惠券（CI-53：total 为发放上限，领取不递减）


-- ---------------------------------------------------------------- 轮播 / 专题 / 公告



-- ---------------------------------------------------------------- 订单（35 单，覆盖 101/102/201/301/401/501/103）

-- 订单行：actual_amount = 行商品金额 - 券分摊；comment=-1 不可评价 / 0 可评价 / >0 评价 ID

-- ---------------------------------------------------------------- 售后 / 退款
-- 退款必须写全 refund_time + aftersale_id（CI-08 只统计 refund_time 落入期且 status=1 的行）


-- ---------------------------------------------------------------- 评价（17 条，全部锚到真实订单行）

-- ---------------------------------------------------------------- 操作日志（D-36：type 1=业务/2=登录，status 0=成功/1=失败）

COMMIT;

-- ============================================================================
-- 核对 SELECT（结果需与 docs/impl/05-种子数据核对.md 一致）
-- ============================================================================
SELECT '1. 订单状态分布' AS check_item;
SELECT order_status, COUNT(*) AS cnt FROM litemall_order WHERE id BETWEEN 998001 AND 998099 AND deleted = 0 GROUP BY order_status ORDER BY order_status;

SELECT '2. 售后状态分布' AS check_item;
SELECT status, COUNT(*) AS cnt FROM litemall_aftersale WHERE id BETWEEN 998501 AND 998599 AND deleted = 0 GROUP BY status ORDER BY status;

SELECT '3. 退款单（status=1 的 refund_time 必须回填）' AS check_item;
SELECT id, aftersale_id, status, amount, refund_time FROM litemall_refund WHERE id BETWEEN 998601 AND 998699 AND deleted = 0 ORDER BY id;

SELECT '4. 评价数（按状态）' AS check_item;
SELECT status, COUNT(*) AS cnt FROM litemall_comment WHERE id BETWEEN 999001 AND 999099 AND deleted = 0 GROUP BY status;

SELECT '5. 券发放数（CI-53：leftCount = total - 已发放数）' AS check_item;
SELECT c.id, c.total AS total_capacity, COUNT(cu.id) AS issued, CASE WHEN c.total <= 0 THEN -1 ELSE c.total - COUNT(cu.id) END AS left_count FROM litemall_coupon c LEFT JOIN litemall_coupon_user cu ON cu.coupon_id = c.id AND cu.deleted = 0 WHERE c.id BETWEEN 994001 AND 994099 AND c.deleted = 0 GROUP BY c.id, c.total ORDER BY c.id;

SELECT '6. 商品 / 多规格商品 / SKU 数' AS check_item;
SELECT (SELECT COUNT(*) FROM litemall_goods WHERE id BETWEEN 993001 AND 993099 AND deleted = 0) AS goods_cnt, (SELECT COUNT(*) FROM (SELECT goods_id FROM litemall_goods_product WHERE goods_id BETWEEN 993001 AND 993099 AND deleted = 0 GROUP BY goods_id HAVING COUNT(*) > 1) x) AS multi_spec_cnt, (SELECT COUNT(*) FROM litemall_goods_product WHERE goods_id BETWEEN 993001 AND 993099 AND deleted = 0) AS sku_cnt;

SELECT '7. 金额一致性（订单实付 = 商品金额 + 运费 - 券抵扣；实付 = 行实付之和）' AS check_item;
SELECT COUNT(*) AS bad_orders FROM (SELECT o.id FROM litemall_order o JOIN litemall_order_goods g ON g.order_id = o.id AND g.deleted = 0 WHERE o.id BETWEEN 998001 AND 998099 AND o.deleted = 0 GROUP BY o.id, o.goods_price, o.freight_price, o.coupon_price, o.actual_price HAVING o.actual_price <> o.goods_price + o.freight_price - o.coupon_price OR o.actual_price <> SUM(g.actual_amount)) t;

SELECT '8. 券分摊一致性（Σcoupon_share = coupon_price，且 Σ行商品金额 = goods_price）' AS check_item;
SELECT COUNT(*) AS bad_lines FROM (SELECT o.id FROM litemall_order o JOIN litemall_order_goods g ON g.order_id = o.id AND g.deleted = 0 WHERE o.id BETWEEN 998001 AND 998099 AND o.deleted = 0 GROUP BY o.id, o.goods_price, o.coupon_price HAVING o.coupon_price <> SUM(g.coupon_share) OR o.goods_price <> SUM(g.price * g.number)) t;

SELECT '9. 评价必须锚到 301/501 订单行' AS check_item;
SELECT COUNT(*) AS bad_comments FROM litemall_comment c JOIN litemall_order o ON o.id = c.order_id WHERE c.id BETWEEN 999001 AND 999099 AND o.order_status NOT IN (301, 501);

SELECT '10. CI-08 三个周期的 GMV / 订单数 / 退款（元，与接口分口径 x100）' AS check_item;
SELECT 'today' AS period, COUNT(*) AS order_cnt, COALESCE(SUM(actual_price), 0) AS gmv, (SELECT COALESCE(SUM(amount), 0) FROM litemall_refund WHERE deleted = 0 AND status = 1 AND refund_time >= CURDATE() AND refund_time < CURDATE() + INTERVAL 1 DAY) AS refund_amt, (SELECT COUNT(DISTINCT aftersale_id) FROM litemall_refund WHERE deleted = 0 AND status = 1 AND refund_time >= CURDATE() AND refund_time < CURDATE() + INTERVAL 1 DAY) AS refund_cnt FROM litemall_order WHERE deleted = 0 AND order_status NOT IN (101, 103) AND pay_time >= CURDATE() AND pay_time < CURDATE() + INTERVAL 1 DAY
UNION ALL SELECT '7d', COUNT(*), COALESCE(SUM(actual_price), 0), (SELECT COALESCE(SUM(amount), 0) FROM litemall_refund WHERE deleted = 0 AND status = 1 AND refund_time >= CURDATE() - INTERVAL 6 DAY AND refund_time < CURDATE() + INTERVAL 1 DAY), (SELECT COUNT(DISTINCT aftersale_id) FROM litemall_refund WHERE deleted = 0 AND status = 1 AND refund_time >= CURDATE() - INTERVAL 6 DAY AND refund_time < CURDATE() + INTERVAL 1 DAY) FROM litemall_order WHERE deleted = 0 AND order_status NOT IN (101, 103) AND pay_time >= CURDATE() - INTERVAL 6 DAY AND pay_time < CURDATE() + INTERVAL 1 DAY
UNION ALL SELECT '30d', COUNT(*), COALESCE(SUM(actual_price), 0), (SELECT COALESCE(SUM(amount), 0) FROM litemall_refund WHERE deleted = 0 AND status = 1 AND refund_time >= CURDATE() - INTERVAL 29 DAY AND refund_time < CURDATE() + INTERVAL 1 DAY), (SELECT COUNT(DISTINCT aftersale_id) FROM litemall_refund WHERE deleted = 0 AND status = 1 AND refund_time >= CURDATE() - INTERVAL 29 DAY AND refund_time < CURDATE() + INTERVAL 1 DAY) FROM litemall_order WHERE deleted = 0 AND order_status NOT IN (101, 103) AND pay_time >= CURDATE() - INTERVAL 29 DAY AND pay_time < CURDATE() + INTERVAL 1 DAY;

SELECT '11. 日志 target_type 覆盖' AS check_item;
SELECT target_type, COUNT(*) AS cnt, SUM(status = 1) AS failed_cnt FROM litemall_log WHERE id BETWEEN 999101 AND 999199 AND deleted = 0 GROUP BY target_type ORDER BY target_type;

SELECT '12. 轮播 / 专题 / 公告' AS check_item;
SELECT (SELECT COUNT(*) FROM litemall_ad WHERE id BETWEEN 995001 AND 995099 AND deleted = 0) AS ad_cnt, (SELECT COUNT(*) FROM litemall_topic WHERE id BETWEEN 996001 AND 996099 AND deleted = 0) AS topic_cnt, (SELECT COUNT(*) FROM litemall_notice WHERE id BETWEEN 997001 AND 997099 AND deleted = 0) AS notice_cnt, (SELECT COUNT(*) FROM litemall_notice WHERE id BETWEEN 997001 AND 997099 AND deleted = 0 AND enabled = 1) AS notice_enabled_cnt;
